import React, { useState, useEffect, useRef, useCallback } from "react";
import {
  absoluteHumidity,
  moistAdiabaticLapseRate,
} from "../utils/meteorology";

// Interaktiv luftmasse komponent
export default function AirMassAnimation({
  startTemp,
  startDewPoint,
  coolingHeight,
  onHeightChange, // Callback til at opdatere graf
  isActive = false,
}) {
  const [currentHeight, setCurrentHeight] = useState(0); // Start på 0 meter
  const [isDragging, setIsDragging] = useState(false);
  const containerRef = useRef(null);
  const isDraggingRef = useRef(false); // Ref til at holde styr på isDragging
  const handlersRef = useRef({}); // Ref til at holde styr på event handlers

  // Beregn værdier baseret på nuværende højde
  const dryLapseRate = 9.8; // °C/km
  const condensationHeight =
    startTemp && startDewPoint ? (startTemp - startDewPoint) / dryLapseRate : 0;

  // Beregn praktisk højde-interval: fra jordoverflade til 1000m over dugpunktshøjde
  const maxPracticalHeight = condensationHeight + 1; // 1km over dugpunktshøjde
  const minHeight = 0; // Jordoverflade
  const maxHeight = Math.max(maxPracticalHeight, 2); // Minimum 2km for at sikre nok plads

  let currentTemp = startTemp;
  let currentPhase = "dry";
  let isSaturated = false;

  if (currentHeight <= condensationHeight) {
    // Tør adiabatisk afkøling
    currentTemp = startTemp - dryLapseRate * currentHeight;
    currentPhase = "dry";
    // Sæt isSaturated til true når vi rammer dugpunktet (præcis ved kondensering)
    isSaturated = Math.abs(currentHeight - condensationHeight) < 0.001; // Tolerans for floating point
  } else {
    // Våd adiabatisk afkøling - brug samme logik som i AdiabaticCoolingApp
    const moistLapseRate = moistAdiabaticLapseRate(startDewPoint); // Brug korrekt funktion
    const remainingHeight = currentHeight - condensationHeight;
    currentTemp = startDewPoint - moistLapseRate * remainingHeight;
    currentPhase = "moist";
    isSaturated = true;
  }

  // Opdater graf når højde ændres
  useEffect(() => {
    if (onHeightChange && startTemp && startDewPoint) {
      onHeightChange(currentHeight, currentTemp, currentPhase, isSaturated);
    }
  }, [
    currentHeight,
    currentTemp,
    currentPhase,
    isSaturated,
    onHeightChange,
    startTemp,
    startDewPoint,
  ]);

  // Nulstil højde når der ikke er input
  useEffect(() => {
    if (!startTemp || !startDewPoint) {
      setCurrentHeight(0); // Reset til 0 meter
    } else {
      // Start på en lille højde (0.1 km) når der er input, så luftmassen kan trækkes op
      setCurrentHeight(0.1);
    }
  }, [startTemp, startDewPoint]);

  // Mouse event handlers - gemt i ref for at undgå closure problemer
  const handleMouseDown = (e) => {
    // Tillad trækning hvis der er temperatur og dugpunkt, selv hvis coolingHeight mangler
    if (!startTemp || !startDewPoint) return;

    // Forbedret responsivitet: Sæt dragging state med det samme
    setIsDragging(true);
    isDraggingRef.current = true;

    // Tilføj touch events for bedre mobil support
    document.addEventListener(
      "mousemove",
      handlersRef.current.handleMouseMove,
      { passive: false }
    );
    document.addEventListener("mouseup", handlersRef.current.handleMouseUp, {
      passive: false,
    });
    document.addEventListener(
      "touchmove",
      handlersRef.current.handleMouseMove,
      { passive: false }
    );
    document.addEventListener("touchend", handlersRef.current.handleMouseUp, {
      passive: false,
    });

    // Forhindre standard browser adfærd
    e.preventDefault();
  };

  const handleMouseMove = (e) => {
    if (!isDraggingRef.current || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const relativeY = e.clientY - rect.top;

    // Forbedret responsivitet: Brug hele containeren og gør trækning mere præcis
    const heightPercent = Math.max(0, Math.min(1, 1 - relativeY / rect.height));

    // Tilføj smoothing for mere flydende bevægelse
    const newHeight = heightPercent * maxHeight; // km

    // Opdater med throttling for bedre performance
    setCurrentHeight(newHeight);

    // Kald onHeightChange med det samme for bedre responsivitet
    if (onHeightChange) {
      onHeightChange(newHeight * 1000); // Konverter til meter
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    isDraggingRef.current = false;

    // Fjern alle event listeners
    document.removeEventListener(
      "mousemove",
      handlersRef.current.handleMouseMove
    );
    document.removeEventListener("mouseup", handlersRef.current.handleMouseUp);
    document.removeEventListener(
      "touchmove",
      handlersRef.current.handleMouseMove
    );
    document.removeEventListener("touchend", handlersRef.current.handleMouseUp);
  };

  // Gem handlers i ref så de altid har adgang til de aktuelle værdier
  handlersRef.current = {
    handleMouseMove,
    handleMouseUp,
  };

  // Beregn sky opacity baseret på afstand fra kondensering punkt
  const getCloudOpacity = () => {
    if (currentPhase !== "moist" || currentHeight <= condensationHeight)
      return 0;
    const distanceAboveCondensation = currentHeight - condensationHeight;
    const maxDistance = 2; // km
    return Math.min(0.8, (distanceAboveCondensation / maxDistance) * 0.8);
  };

  // Beregn volumen baseret på temperatur og højde (luft udvider sig når den stiger)
  const getVolumeScale = () => {
    if (!startTemp || !currentTemp) return 0.5; // Start endnu mindre

    // Kombiner temperatur- og højdebaseret udvidelse
    const tempRatio = (currentTemp + 273.15) / (startTemp + 273.15);
    const heightRatio = currentHeight / Math.max(maxHeight, 1); // Normaliser højde

    // Base størrelse + temperatur udvidelse + højde udvidelse (mindre voldsom)
    const baseScale = 0.5;
    const tempExpansion = Math.max(0, (tempRatio - 1) * 0.6); // Reduceret fra 1.2 til 0.6
    const heightExpansion = heightRatio * 0.8; // Reduceret fra 1.5 til 0.8

    const totalScale = baseScale + tempExpansion + heightExpansion;
    return Math.max(0.5, Math.min(1.8, totalScale)); // Reduceret maksimum fra 2.5 til 1.8
  };

  // Farver baseret på fase og mætning - hvid til grå overgang
  const getAirMassColor = () => {
    if (currentPhase === "dry") {
      if (isSaturated) {
        // Hvid når den rammer dugpunktet
        return "bg-white border-gray-300";
      } else {
        // Lys orange når umættet
        return "bg-orange-100 border-orange-300";
      }
    } else {
      // Våd adiabatisk - grå overgang baseret på højde over kondensering
      const distanceAboveCondensation = currentHeight - condensationHeight;
      const maxDistance = 1; // km
      const grayIntensity = Math.min(
        1,
        distanceAboveCondensation / maxDistance
      );

      if (grayIntensity < 0.3) {
        return "bg-gray-100 border-gray-300"; // Meget lys grå
      } else if (grayIntensity < 0.6) {
        return "bg-gray-200 border-gray-400"; // Lys grå
      } else {
        return "bg-gray-300 border-gray-500"; // Mørkere grå
      }
    }
  };

  const getStatusText = () => {
    if (currentPhase === "dry") {
      if (isSaturated) {
        return "MÆTTET (Ved dugpunkt)";
      } else {
        return "UMÆTTET (Tør adiabatisk)";
      }
    } else {
      return "MÆTTET (Våd adiabatisk)";
    }
  };

  const getStatusColor = () => {
    if (currentPhase === "dry") {
      return isSaturated ? "text-yellow-700" : "text-orange-700";
    } else {
      return "text-blue-700";
    }
  };

  return (
    <div className="w-full h-full bg-gradient-to-b from-blue-100 to-blue-200 rounded-lg border-2 border-gray-300 relative overflow-visible">
      {/* Højde skala - dynamisk baseret på praktisk interval */}
      <div className="absolute left-2 top-0 bottom-0 w-8 flex flex-col justify-between text-xs text-gray-600">
        {(() => {
          const steps = 5;
          const heights = [];
          for (let i = 0; i <= steps; i++) {
            const height = (maxHeight * 1000 * i) / steps; // Konverter til meter
            heights.push(height);
          }
          return heights.reverse().map((height) => {
            // Rund til pæne hele hundreder/tusinder
            let roundedHeight;
            if (height >= 1000) {
              roundedHeight = Math.round(height / 1000) * 1000; // Rund til tusinder
            } else if (height >= 100) {
              roundedHeight = Math.round(height / 100) * 100; // Rund til hundreder
            } else {
              roundedHeight = Math.round(height); // Rund til hele meter
            }
            return (
              <div key={height} className="text-center">
                {roundedHeight}m
              </div>
            );
          });
        })()}
      </div>

      {/* Højde linjer - dynamisk baseret på praktisk interval */}
      <div className="absolute left-10 top-0 bottom-0 w-full">
        {(() => {
          const steps = 5;
          const heights = [];
          for (let i = 0; i <= steps; i++) {
            const height = (maxHeight * 1000 * i) / steps; // Konverter til meter
            heights.push(height);
          }
          return heights.map((height) => {
            // Rund til pæne hele hundreder/tusinder (samme logik som skalaen)
            let roundedHeight;
            if (height >= 1000) {
              roundedHeight = Math.round(height / 1000) * 1000; // Rund til tusinder
            } else if (height >= 100) {
              roundedHeight = Math.round(height / 100) * 100; // Rund til hundreder
            } else {
              roundedHeight = Math.round(height); // Rund til hele meter
            }
            return (
              <div
                key={height}
                className="absolute w-full border-t border-gray-300 border-dashed"
                style={{ bottom: `${(height / (maxHeight * 1000)) * 100}%` }}
                title={`${roundedHeight}m`}
              />
            );
          });
        })()}
      </div>

      {/* Interaktiv luftmasse - større container for nemmere trækning */}
      <div
        ref={containerRef}
        className="absolute left-16 top-0 bottom-0 w-32 cursor-pointer"
        onMouseDown={handleMouseDown}
      >
        <div
          className={`absolute w-16 h-16 rounded-full border-2 ${getAirMassColor()} flex flex-col items-center justify-center text-xs font-medium transition-all duration-200 ${
            isDragging ? "scale-110 shadow-lg" : "hover:scale-105"
          }`}
          style={{
            bottom: `${Math.max(0, (currentHeight / maxHeight) * 100)}%`,
            left: "2px", // Centrer i containeren
            transform: `translateY(50%) scale(${getVolumeScale()})`, // Centrer vertikalt og skaler
          }}
        >
          {/* Temperatur og luftfugtighed visning */}
          <div className="text-xs font-bold text-gray-800">
            {currentTemp
              ? `${currentTemp.toFixed(1).replace(".", ",")}°C`
              : "N/A"}
          </div>
          <div className="text-xs text-gray-600">
            {currentPhase === "dry" ? "Tør" : "Våd"}
          </div>
          {/* Drag handle indikation */}
          <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-8 h-1 bg-gray-400 rounded-full opacity-60"></div>
        </div>
      </div>

      {/* Kondensering start punkt - vandret stiplet linje */}
      {condensationHeight > 0 && condensationHeight <= maxHeight && (
        <div
          className="absolute left-16 right-2 h-0.5 bg-green-500 border-t-2 border-green-700 border-dashed"
          style={{
            bottom: `${(condensationHeight / maxHeight) * 100}%`,
          }}
        />
      )}

      {/* Drag instruktion */}
      {!isActive && (
        <div className="absolute inset-0 flex items-center justify-center bg-gray-100 bg-opacity-80 rounded-lg">
          <div className="text-center text-gray-600">
            <div className="text-lg mb-2">Indtast temperatur og dugpunkt</div>
            <div className="text-sm">for at aktivere luftmasse</div>
          </div>
        </div>
      )}
    </div>
  );
}
