import React, { useMemo, useState, useEffect, lazy, Suspense } from "react";
import {
  absoluteHumidity,
  dryAdiabaticLapseRate,
  moistAdiabaticLapseRate,
} from "../utils/meteorology";
import AirMassAnimation from "./AirMassAnimation";

// Lazy load Plotly for bedre performance
const Plot = lazy(() => import("react-plotly.js"));

// Loading komponent for Plotly
const PlotLoader = () => (
  <div className="flex items-center justify-center p-8">
    <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600"></div>
    <span className="ml-2 text-gray-600">Indlæser graf...</span>
  </div>
);

// Adiabatisk afkøling komponent
export default function AdiabaticCoolingApp() {
  const [plotKey, setPlotKey] = useState(0);
  const [inputTemp, setInputTemp] = useState("");
  const [inputDewPoint, setInputDewPoint] = useState("");
  const [currentZoom, setCurrentZoom] = useState({ x: [-10, 40], y: [0, 50] });
  const [coolingHeight, setCoolingHeight] = useState(1000);
  const [interactiveHeight, setInteractiveHeight] = useState(0);
  const [interactiveTemp, setInteractiveTemp] = useState(null);
  const [interactivePhase, setInteractivePhase] = useState("dry");
  const [interactiveSaturated, setInteractiveSaturated] = useState(false);

  const xs = useMemo(() => {
    const arr = [];
    for (let t = -45; t <= 60 + 1e-9; t += 0.25)
      arr.push(parseFloat(t.toFixed(6)));
    return arr;
  }, []);

  const ys = useMemo(() => xs.map((T) => absoluteHumidity(T)), [xs]);

  // Beregn nedbør fra vandoverskud
  function calculatePrecipitation() {
    if (!inputTemp || !inputDewPoint) return null;

    const startTemp = parseFloat(inputTemp);
    const startDewPoint = parseFloat(inputDewPoint);
    const heightKm = coolingHeight / 1000;

    const dryLapseRate = dryAdiabaticLapseRate();
    const condensationHeight = (startTemp - startDewPoint) / dryLapseRate;

    if (condensationHeight >= heightKm) return null; // Ingen kondensering

    // Beregn vandoverskud fra start til slut
    const startHumidity = absoluteHumidity(startDewPoint);
    const finalTemp =
      startDewPoint -
      moistAdiabaticLapseRate(startDewPoint) * (heightKm - condensationHeight);
    const finalHumidity = absoluteHumidity(finalTemp);

    const waterExcess = startHumidity - finalHumidity; // g/m³

    // Korrekt nedbørberegning: vandoverskud pr. m³ luft
    // Dette er den faktiske mængde vand der kondenserer ud af luften
    const precipitationMm = waterExcess; // mm (1 g/m³ ≈ 1 mm/m³ luft)

    return {
      waterExcess: waterExcess.toFixed(2).replace(".", ","),
      precipitationMm: precipitationMm.toFixed(2).replace(".", ","),
      condensationHeight: (condensationHeight * 1000).toFixed(0),
      finalTemp: finalTemp.toFixed(1).replace(".", ","),
      explanation: `Vandoverskud: ${waterExcess
        .toFixed(2)
        .replace(
          ".",
          ","
        )} g/m³ luft kondenserer ud når luften afkøles fra ${startDewPoint
        .toFixed(1)
        .replace(".", ",")}°C til ${finalTemp.toFixed(1).replace(".", ",")}°C`,
    };
  }

  function calculateCoolingTraces() {
    if (!inputTemp || !inputDewPoint) {
      return [];
    }

    const startTemp = parseFloat(inputTemp);
    const startDewPoint = parseFloat(inputDewPoint);
    const heightKm = coolingHeight / 1000; // Konverter til km

    // Beregn adiabatisk afkøling
    const dryLapseRate = dryAdiabaticLapseRate();

    // Tør adiabatisk afkøling (luftpakken afkøles uden kondensering)
    const dryCooledTemp = startTemp - dryLapseRate * heightKm;
    const dryCooledHumidity = absoluteHumidity(startDewPoint); // Luftfugtighed forbliver konstant

    // Find hvor den tørre adiabatiske linje krydser mætningskurven (dewpoint level)
    const condensationTemp = startDewPoint; // Kondensering starter ved dugpunktets temperatur
    const condensationHeight = (startTemp - condensationTemp) / dryLapseRate; // km

    const traces = [];

    // Tør adiabatisk linje - kun til kondensering starter
    if (condensationHeight < heightKm) {
      // Del 1: Tør adiabatisk til kondensering
      traces.push({
        x: [startTemp, condensationTemp],
        y: [
          absoluteHumidity(startDewPoint),
          absoluteHumidity(condensationTemp),
        ],
        type: "scatter",
        mode: "lines",
        name: "Tør adiabatisk afkøling",
        line: {
          color: "#f59e0b", // Orange
          width: 5,
          dash: "dot",
        },
        hovertemplate: `Tør adiabatisk<br>Fra: ${startTemp
          .toFixed(1)
          .replace(".", ",")}°C<br>Til: ${condensationTemp
          .toFixed(1)
          .replace(".", ",")}°C (kondensering)<extra></extra>`,
      });

      // Del 2: Våd adiabatisk langs mætningskurven
      const remainingHeight = heightKm - condensationHeight;
      const moistLapseRate = moistAdiabaticLapseRate(condensationTemp);
      const finalTemp = condensationTemp - moistLapseRate * remainingHeight;

      // Generer punkter langs mætningskurven
      const moistPoints = [];
      const numPoints = 20;
      for (let i = 0; i <= numPoints; i++) {
        const tempProgress = i / numPoints;
        const currentTemp =
          condensationTemp - (condensationTemp - finalTemp) * tempProgress;
        moistPoints.push({
          x: currentTemp,
          y: absoluteHumidity(currentTemp),
        });
      }

      traces.push({
        x: moistPoints.map((p) => p.x),
        y: moistPoints.map((p) => p.y),
        type: "scatter",
        mode: "lines",
        name: "Våd adiabatisk afkøling",
        line: {
          color: "#dc2626", // Rød
          width: 5,
          dash: "dot",
        },
        hovertemplate: `Våd adiabatisk<br>Fra: ${condensationTemp
          .toFixed(1)
          .replace(".", ",")}°C<br>Til: ${finalTemp
          .toFixed(1)
          .replace(".", ",")}°C<br>Følger mætningskurven<extra></extra>`,
      });

      // Slutpunkt for våd adiabatisk
      traces.push({
        x: [finalTemp],
        y: [absoluteHumidity(finalTemp)],
        type: "scatter",
        mode: "markers",
        name: "Våd slutpunkt",
        marker: {
          color: "#dc2626",
          size: 10,
          symbol: "diamond",
        },
        hovertemplate: `Våd slutpunkt<br>T: ${finalTemp
          .toFixed(1)
          .replace(".", ",")}°C<br>På mætningskurven<extra></extra>`,
      });

      // Kondensering punkt
      traces.push({
        x: [condensationTemp],
        y: [absoluteHumidity(condensationTemp)],
        type: "scatter",
        mode: "markers",
        name: "Kondensering starter",
        marker: {
          color: "#10b981", // Grøn
          size: 10,
          symbol: "circle",
        },
        hovertemplate: `Kondensering starter<br>T: ${condensationTemp
          .toFixed(1)
          .replace(".", ",")}°C<br>Højde: ${(condensationHeight * 1000).toFixed(
          0
        )}m<extra></extra>`,
      });
    } else {
      // Kun tør adiabatisk afkøling (når vi ikke når kondensering)
      traces.push({
        x: [startTemp, dryCooledTemp],
        y: [absoluteHumidity(startDewPoint), dryCooledHumidity],
        type: "scatter",
        mode: "lines",
        name: "Tør adiabatisk afkøling",
        line: {
          color: "#f59e0b", // Orange
          width: 5,
          dash: "dot",
        },
        hovertemplate: `Tør adiabatisk<br>Fra: ${startTemp
          .toFixed(1)
          .replace(".", ",")}°C<br>Til: ${dryCooledTemp
          .toFixed(1)
          .replace(".", ",")}°C<br>Højde: ${coolingHeight}m<extra></extra>`,
      });

      // Slutpunkt for tør adiabatisk
      traces.push({
        x: [dryCooledTemp],
        y: [dryCooledHumidity],
        type: "scatter",
        mode: "markers",
        name: "Tør slutpunkt",
        marker: {
          color: "#f59e0b",
          size: 10,
          symbol: "diamond",
        },
        hovertemplate: `Tør slutpunkt<br>T: ${dryCooledTemp
          .toFixed(1)
          .replace(".", ",")}°C<extra></extra>`,
      });
    }

    // Startpunkt
    traces.push({
      x: [startTemp],
      y: [absoluteHumidity(startDewPoint)],
      type: "scatter",
      mode: "markers",
      name: "Startpunkt",
      marker: {
        color: "#3b82f6",
        size: 12,
        symbol: "circle",
      },
      hovertemplate: `Startpunkt<br>T: ${startTemp
        .toFixed(1)
        .replace(".", ",")}°C<br>Dugpunkt: ${startDewPoint
        .toFixed(1)
        .replace(".", ",")}°C<extra></extra>`,
    });

    return traces;
  }

  // Callback funktion til at opdatere graf fra animation
  const handleHeightChange = (height, temp, phase, saturated) => {
    setInteractiveHeight(height);
    setInteractiveTemp(temp);
    setInteractivePhase(phase);
    setInteractiveSaturated(saturated);
    // Opdater coolingHeight altid når der trækkes i animationen
    const interactiveHeightM = Math.round(height * 1000);
    setCoolingHeight(interactiveHeightM);
  };

  const data = useMemo(() => {
    const traces = [
      {
        x: xs,
        y: ys,
        type: "scatter",
        mode: "lines",
        name: "Mætningskurve",
        line: {
          width: 3,
          color: "#3b82f6",
          shape: "spline",
        },
        hovertemplate: `T: %{x:.2f} °C<br>Luftfugtighed: %{y:.2f} g/m³<extra></extra>`,
      },
      // Tilføj adiabatiske afkølingslinjer
      ...calculateCoolingTraces(),
    ];

    return traces;
  }, [
    xs,
    ys,
    inputTemp,
    inputDewPoint,
    coolingHeight,
    interactiveHeight,
    interactiveTemp,
    interactivePhase,
    interactiveSaturated,
  ]);

  const layout = {
    title: {
      text: "ADIABATISK AFKØLING",
      font: { size: 20, color: "#374151" },
      x: 0.5,
    },
    xaxis: {
      title: "Temperatur (°C)",
      range: currentZoom.x,
      gridcolor: "#e5e7eb",
      zerolinecolor: "#d1d5db",
    },
    yaxis: {
      title: "Absolut luftfugtighed (g/m³)",
      range: currentZoom.y,
      gridcolor: "#e5e7eb",
      zerolinecolor: "#d1d5db",
    },
    plot_bgcolor: "white",
    paper_bgcolor: "white",
    font: { color: "#374151" },
    legend: {
      x: 0.02,
      y: 0.98,
      bgcolor: "rgba(255, 255, 255, 0.8)",
      bordercolor: "#d1d5db",
      borderwidth: 1,
    },
    margin: { l: 60, r: 30, t: 60, b: 60 },
    hovermode: "closest",
  };

  const config = {
    displayModeBar: true,
    modeBarButtonsToRemove: ["pan2d", "lasso2d", "select2d"],
    displaylogo: false,
    toImageButtonOptions: {
      format: "png",
      filename: "adiabatic-cooling",
      height: 600,
      width: 1200,
      scale: 2,
    },
  };

  const resetAndClear = () => {
    setPlotKey((k) => k + 1);
    setInputTemp("");
    setInputDewPoint("");
    setCoolingHeight(100); // Start med 100m i stedet for 1000m
    setInteractiveHeight(0.1); // Start med 0.1km som animationen
    setInteractiveTemp(null);
    setInteractivePhase("dry");
    setInteractiveSaturated(false);
  };

  return (
    <div className="p-6">
      <div className="flex flex-col xl:flex-row gap-6">
        {/* Venstre side - Kontrolpanel */}
        <div className="xl:w-80 flex-shrink-0">
          <div className="p-4 border rounded-xl bg-gray-50 h-fit">
            <p className="text-sm text-slate-600 mb-4">
              Se hvad der sker med luften når den afkøles adiabatisk. Tør
              adiabatisk afkøling sker uden kondensering, mens våd adiabatisk
              afkøling følger mætningskurven efter kondensering starter.
            </p>

            <div className="space-y-4 mb-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Starttemperatur (°C)
                </label>
                <input
                  type="number"
                  value={inputTemp}
                  onChange={(e) => {
                    const value = e.target.value;
                    if (value === "" || value === "-") {
                      setInputTemp(value);
                    } else {
                      const numValue = parseFloat(value);
                      if (
                        !isNaN(numValue) &&
                        numValue >= -45 &&
                        numValue <= 60
                      ) {
                        setInputTemp(value);
                      }
                    }
                  }}
                  placeholder="Indtast temperatur (-45 til 60°C)"
                  className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                    inputTemp &&
                    inputTemp !== "" &&
                    inputTemp !== "-" &&
                    (parseFloat(inputTemp) < -45 || parseFloat(inputTemp) > 60)
                      ? "border-red-500 bg-red-50"
                      : "border-gray-300"
                  }`}
                  step="0.1"
                  min="-45"
                  max="60"
                />
                {inputTemp &&
                  inputTemp !== "" &&
                  inputTemp !== "-" &&
                  (parseFloat(inputTemp) < -45 ||
                    parseFloat(inputTemp) > 60) && (
                    <p className="text-xs text-red-600 mt-1">
                      Temperatur skal være mellem -45°C og 60°C
                    </p>
                  )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Dugpunktstemperatur (°C)
                </label>
                <input
                  type="number"
                  value={inputDewPoint}
                  onChange={(e) => {
                    const value = e.target.value;
                    if (value === "" || value === "-") {
                      setInputDewPoint(value);
                    } else {
                      const numValue = parseFloat(value);
                      const tempValue = inputTemp
                        ? parseFloat(inputTemp)
                        : null;
                      if (
                        !isNaN(numValue) &&
                        numValue >= -45 &&
                        numValue <= 60 &&
                        (tempValue === null || numValue <= tempValue)
                      ) {
                        setInputDewPoint(value);
                      }
                    }
                  }}
                  placeholder="Indtast dugpunkt (-45 til 60°C)"
                  className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                    inputDewPoint &&
                    inputDewPoint !== "" &&
                    inputDewPoint !== "-" &&
                    (parseFloat(inputDewPoint) < -45 ||
                      parseFloat(inputDewPoint) > 60 ||
                      (inputTemp &&
                        parseFloat(inputDewPoint) > parseFloat(inputTemp)))
                      ? "border-red-500 bg-red-50"
                      : "border-gray-300"
                  }`}
                  step="0.1"
                  min="-45"
                  max="60"
                />
                {inputDewPoint &&
                  inputDewPoint !== "" &&
                  inputDewPoint !== "-" &&
                  (parseFloat(inputDewPoint) < -45 ||
                    parseFloat(inputDewPoint) > 60 ||
                    (inputTemp &&
                      parseFloat(inputDewPoint) > parseFloat(inputTemp))) && (
                    <p className="text-xs text-red-600 mt-1">
                      {parseFloat(inputDewPoint) < -45 ||
                      parseFloat(inputDewPoint) > 60
                        ? "Dugpunkt skal være mellem -45°C og 60°C"
                        : "Dugpunkt kan ikke være højere end temperaturen"}
                    </p>
                  )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Afkølingshøjde (m)
                </label>
                <input
                  type="number"
                  value={coolingHeight}
                  onChange={(e) => {
                    const value = parseInt(e.target.value);
                    if (!isNaN(value) && value >= 100 && value <= 10000) {
                      setCoolingHeight(value);
                    }
                  }}
                  placeholder="1000"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  min="100"
                  max="10000"
                  step="100"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Vælg højde fra 100m til 10km. Animationen justerer automatisk
                  intervallet.
                </p>
              </div>
            </div>

            <div className="space-y-2">
              <button
                onClick={resetAndClear}
                className="w-full px-3 py-3 border rounded-lg bg-red-50 hover:bg-red-100 text-red-700 border-red-300"
              >
                Ryd og nulstil
              </button>
            </div>

            {inputTemp && inputDewPoint && (
              <div className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                <h3 className="font-semibold text-blue-800 mb-2 text-sm">
                  Adiabatisk afkøling
                </h3>
                <p className="text-xs text-blue-600 mb-3">
                  Se hvad der sker med luften når den afkøles adiabatisk
                </p>

                <div className="text-xs text-blue-700 space-y-1">
                  <p>
                    <strong>Startpunkt:</strong>{" "}
                    {parseFloat(inputTemp).toFixed(1).replace(".", ",")}°C,
                    dugpunkt:{" "}
                    {parseFloat(inputDewPoint).toFixed(1).replace(".", ",")}°C
                  </p>
                  {(() => {
                    const startTemp = parseFloat(inputTemp);
                    const startDewPoint = parseFloat(inputDewPoint);
                    const heightKm = coolingHeight / 1000;
                    const dryLapseRate = dryAdiabaticLapseRate();
                    const condensationHeight =
                      (startTemp - startDewPoint) / dryLapseRate;

                    if (condensationHeight < heightKm) {
                      // Kondensering sker
                      const remainingHeight = heightKm - condensationHeight;
                      const moistLapseRate =
                        moistAdiabaticLapseRate(startDewPoint);
                      const finalTemp =
                        startDewPoint - moistLapseRate * remainingHeight;

                      return (
                        <>
                          <p>
                            <strong>Tør adiabatisk:</strong>{" "}
                            {startTemp.toFixed(1).replace(".", ",")}°C →{" "}
                            {startDewPoint.toFixed(1).replace(".", ",")}°C
                            <span className="text-xs">
                              {" "}
                              (til kondensering ved{" "}
                              {(condensationHeight * 1000).toFixed(0)}m)
                            </span>
                          </p>
                          <p>
                            <strong>Våd adiabatisk:</strong>{" "}
                            {startDewPoint.toFixed(1).replace(".", ",")}°C →{" "}
                            {finalTemp.toFixed(1).replace(".", ",")}°C
                            <span className="text-xs">
                              {" "}
                              (langs mætningskurven)
                            </span>
                          </p>
                        </>
                      );
                    } else {
                      // Ingen kondensering
                      const finalTemp = startTemp - dryLapseRate * heightKm;
                      return (
                        <p>
                          <strong>Kun tør adiabatisk:</strong>{" "}
                          {startTemp.toFixed(1).replace(".", ",")}°C →{" "}
                          {finalTemp.toFixed(1).replace(".", ",")}°C
                          <span className="text-xs"> (ingen kondensering)</span>
                        </p>
                      );
                    }
                  })()}

                  {/* Nedbørberegning */}
                  {(() => {
                    const precip = calculatePrecipitation();
                    if (precip) {
                      return (
                        <div className="mt-3 p-2 bg-green-50 border border-green-200 rounded">
                          <h4 className="font-semibold text-green-800 text-xs mb-1">
                            Vandoverskud ved adiabatisk afkøling:
                          </h4>
                          <div className="text-xs text-green-700 space-y-1">
                            <p>
                              <strong>Vandoverskud:</strong>{" "}
                              {precip.waterExcess} g/m³ luft
                            </p>
                            <p>
                              <strong>Kondensering starter:</strong>{" "}
                              {precip.condensationHeight}m
                            </p>
                            <p>
                              <strong>Sluttemperatur:</strong>{" "}
                              {precip.finalTemp}°C
                            </p>
                            <p className="text-xs text-green-600 mt-1 italic">
                              {precip.explanation}
                            </p>
                          </div>
                        </div>
                      );
                    }
                    return null;
                  })()}

                  <p className="text-xs text-blue-600 mt-2">
                    <strong>Adiabatisk afkøling pr 100m:</strong>
                    <br />
                    <strong>Tør adiabatisk:</strong> 0,98°C/100m (9,8°C/km)
                    <br />
                    <strong>Våd adiabatisk:</strong> ~0,65°C/100m
                    (temperaturafhængig)
                    <br />
                    <br />
                    <strong>Orange stiplede linje:</strong> Tør adiabatisk
                    (9,8°C/km)
                    <br />
                    <strong>Rød prikkede linje:</strong> Våd adiabatisk (følger
                    mætningskurven)
                    <br />
                    <strong>Grøn stiplet linje:</strong> Kondensering starter
                  </p>
                </div>
              </div>
            )}

            <p className="mt-4 text-xs text-slate-500">
              Magnus formel (Sonntag90): Ew = α·exp((β·T)/(λ+T)) hvor α=6.112
              hPa, β=17.62, λ=243.12 °C.
            </p>
            <p className="mt-2 text-xs text-slate-400 text-center">
              Philip K. Jakobsen
            </p>
          </div>
        </div>

        {/* Højre side - Graf og Animation */}
        <div className="flex-1">
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
            {/* Graf */}
            <div className="xl:col-span-2 rounded-xl border">
              <Suspense fallback={<PlotLoader />}>
                <Plot
                  key={plotKey}
                  data={data}
                  layout={{ ...layout, autosize: true }}
                  style={{
                    width: "100%",
                    height: "70vh",
                  }}
                  config={config}
                  useResizeHandler
                  onRelayout={(eventData) => {
                    if (
                      eventData["xaxis.range[0]"] !== undefined &&
                      eventData["xaxis.range[1]"] !== undefined &&
                      eventData["yaxis.range[0]"] !== undefined &&
                      eventData["yaxis.range[1]"] !== undefined
                    ) {
                      setCurrentZoom({
                        x: [
                          eventData["xaxis.range[0]"],
                          eventData["xaxis.range[1]"],
                        ],
                        y: [
                          eventData["yaxis.range[0]"],
                          eventData["yaxis.range[1]"],
                        ],
                      });
                    }
                  }}
                />
              </Suspense>
            </div>

            {/* Animation */}
            <div className="xl:col-span-1">
              <div className="bg-white rounded-xl border p-4">
                <h3 className="text-lg font-semibold text-gray-800 mb-4">
                  Animation af luftmassen
                </h3>
                <p className="text-xs text-gray-600 mb-2 text-center">
                  Træk luftmassen op og ned
                </p>
                <div className="h-[55vh]">
                  <AirMassAnimation
                    startTemp={inputTemp ? parseFloat(inputTemp) : null}
                    startDewPoint={
                      inputDewPoint ? parseFloat(inputDewPoint) : null
                    }
                    coolingHeight={coolingHeight}
                    onHeightChange={handleHeightChange}
                    isActive={!!(inputTemp && inputDewPoint && coolingHeight)}
                  />
                </div>
                <div className="text-xs text-gray-600 mt-2 text-center">
                  {inputTemp && inputDewPoint && coolingHeight ? (
                    <div className="text-center">
                      {(() => {
                        const currentHeight = coolingHeight / 1000; // km
                        const condensationHeight =
                          ((inputTemp - inputDewPoint) / 9.8) * 1000; // m
                        if (currentHeight * 1000 <= condensationHeight) {
                          return (
                            <div className="text-orange-600 font-medium">
                              Tør adiabatisk: 1,0°C/100m
                            </div>
                          );
                        } else {
                          return (
                            <div className="text-red-600 font-medium">
                              Våd adiabatisk: 0,65°C/100m
                            </div>
                          );
                        }
                      })()}
                    </div>
                  ) : (
                    "Træk luftmassen op og ned"
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
